      if (!assetId) return;
      const resolved = {
        file: authoredPayloadFileForEntity({ type: 'payload', data: { authoredPayloadAssetId: assetId } }),
        slot: authoredPayloadSlotForEntity({ type: 'payload', data: { authoredPayloadAssetId: assetId } }),
      };
